#include <string>
#include <vector>

class Solution {
public:
    int numberOfArrays(std::string s, int k) {
        long long MOD = 1000000007;
        int n = s.size();
        std::vector<int> dp(n + 1, 0);
        dp[n] = 1;
        for (int i = n - 1; i >= 0; --i) {
            if (s[i] == '0') continue;
            long long val = 0;
            for (int j = i; j < n; ++j) {
                val = val * 10 + (s[j] - '0');
                if (val > k) break;
                dp[i] = (dp[i] + dp[j + 1]) % MOD;
            }
        }
        return dp[0];
    }
};

class Solution {
    public int numberOfArrays(String s, int k) {
        long MOD = 1000000007L;
        int n = s.length();
        int[] dp = new int[n + 1];
        dp[n] = 1;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == '0') continue;
            long val = 0;
            for (int j = i; j < n; j++) {
                val = val * 10 + (s.charAt(j) - '0');
                if (val > k) break;
                dp[i] = (int)((dp[i] + dp[j + 1]) % MOD);
            }
        }
        return dp[0];
    }
}

var numberOfArrays = function(s, k) {
    const MOD = 1000000007;
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    dp[n] = 1;
    for (let i = n - 1; i >= 0; i--) {
        if (s[i] === '0') continue;
        let val = 0;
        for (let j = i; j < n; j++) {
            val = val * 10 + (s.charCodeAt(j) - 48);
            if (val > k) break;
            dp[i] = (dp[i] + dp[j + 1]) % MOD;
        }
    }
    return dp[0];
};
